if (r == 0.0 && k > 0) {
        return 0.0;
    }

    // Calculate sqrt(n! / (n+k)!)
    double factorial_ratio = 1.0;
    for (size_t i = 1; i <= k; ++i) {
        factorial_ratio /= std::sqrt(static_cast<double>(n + i));
    }

    // Calculate L_n^k(4*r^2) using recurrence relation
    double x = 4.0 * r * r;
    double ln_k = 0.0;
    if (n == 0) {
        ln_k = 1.0;
    } else if (n == 1) {
        ln_k = 1.0 + static_cast<double>(k) - x;
    } else {
        double l_prev2 = 1.0; // L_0^k
        double l_prev1 = 1.0 + static_cast<double>(k) - x; // L_1^k
        for (size_t i = 1; i < n; ++i) {
            double current = ((2.0 * i + static_cast<double>(k) + 1.0 - x) * l_prev1 - 
                             (static_cast<double>(i) + static_cast<double>(k)) * l_prev2) / 
                             (static_cast<double>(i) + 1.0);
            l_prev2 = l_prev1;
            l_prev1 = current;
        }
        ln_k = l_prev1;
    }

    // Combine all terms: (-1)^n / pi * ratio * exp(-2r^2) * (2r)^k * L_n^k
    double sign = (n % 2 == 0) ? 1.0 : -1.0;
    double pi = std::acos(-1.0);
    double result = (sign / pi) * factorial_ratio * std::exp(-2.0 * r * r) * std::pow(2.0 * r, static_cast<double>(k)) * ln_k;

    return result;

